import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context'
import { BANNER_ACTIONS } from '../actions'

export const useDashboardBannerContext = () => {
  const [{ getPossiblePositionsData, addBannerData, bannerListData }, dispatch] = useEBContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const getPossiblePositionsRequest = (query = {}) => {
    callApi(BANNER_ACTIONS.getPossiblePositions({ query }))
  }

  const bannerListRequest = useCallback((query = {}) => {
    callApi(BANNER_ACTIONS.getBannerList({ query }))
  }, [callApi])

  const addBannerRequest = (payload = {}) => {
    callApi(BANNER_ACTIONS.addBannerRequest({ body: payload }))
  }

  const updateBannerRequest = (payload = {}) => {
    const bannerId = payload.id
    callApi(BANNER_ACTIONS.updateBannerRequest({ body: payload, bannerId }))
  }

  const removeBannerRequest = (bannerId) => {
    callApi(BANNER_ACTIONS.removeBanner(bannerId))
  }

  const resetState = (keys = []) => {
    dispatch(BANNER_ACTIONS.resetState(keys))
  }

  return {
    getPossiblePositionsRequest,
    getPossiblePositionsData,
    addBannerData,
    addBannerRequest,
    bannerListData,
    bannerListRequest,
    removeBannerRequest,
    updateBannerRequest,
    resetState
  }
}
