import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Row, Col, Button, Icon, Table, Spin, message, Alert, Modal } from 'antd'
import React, { useEffect } from 'react'
import { EbSectionWrapper } from '../../../CommonComponents'
import { ColTextAlignRight, RowWithMargin } from '../../../CommonComponents/index.style'
import { useDashboardBannerContext } from '../../../state/DashboardBanner/hooks/useDashboardBanner'
import { bannerColumns } from './utility'
import lodash from 'lodash'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const DashboardBanner = ({ history }) => {
  const { bannerListData, bannerListRequest, removeBannerRequest } = useDashboardBannerContext()
  const [{ BANNER_LIST_LOADER, REMOVE_BANNER_LOADER }] = useLoaderContextValue()
  const [{ REMOVE_BANNER_ERROR, removeBannerStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const handleEdit = rowData => {
    history.push({
      pathname: '/employee-benefits/dashboard-banner/edit',
      state: rowData
    })
  }

  const handleRemoveBanner = bannerId => {
    resetError(['removeBannerStatus'])
    removeBannerRequest(bannerId)
  }

  const handleAddBanner = () => {
    const bannerList = lodash.get(bannerListData, 'data')
    if (Array.isArray(bannerList) && bannerList.length === 4) {
      Modal.error({
        title: 'Banner limit is reached.',
        content: 'You’ve reached the maximum banner slot of 4. Please delete one to create new banner.'
      })
    } else {
      history.push('/employee-benefits/dashboard-banner/add')
    }
  }

  useEffect(() => {
    if (removeBannerStatus === 'success') {
      message.success('Banner removed successfully')
      bannerListRequest()
    }
  }, [removeBannerStatus, bannerListRequest])

  useEffect(() => {
    bannerListRequest()
    return () => resetError([
      'removeBannerStatus',
      'REMOVE_BANNER_ERROR'
    ])
  }, [bannerListRequest, resetError])

  return (
    <EbSectionWrapper>
      {(REMOVE_BANNER_ERROR) && <Alert type='error' message={removeBannerStatus} banner />}
      <Spin spinning={!!BANNER_LIST_LOADER || !!REMOVE_BANNER_LOADER}>
        <Row>
          <Col span={8}>
            <h2>Banner List</h2>
          </Col>
          <ColTextAlignRight span={16}>
            <PermissionCheckerV2 requiredPermission='ops.eb_create_banner'>
              <Button
                type='primary'
                onClick={handleAddBanner}
              >
                Add Banner <Icon type='plus' />
              </Button>
            </PermissionCheckerV2>
          </ColTextAlignRight>
        </Row>
        <RowWithMargin>
          <Table
            dataSource={bannerListData ? bannerListData.data : []}
            columns={bannerColumns({ handleRemoveBanner, handleEdit })}
            rowKey={rowData => rowData.id}
          />
        </RowWithMargin>
      </Spin>
    </EbSectionWrapper>
  )
}
export default DashboardBanner
